  sp.start("Sincronizando configuracoes...");
  const results = syncAllProviders(providers, ctx.projectRoot, config.servers);
  sp.stop("Sincronizacao concluida.");
  let updated = 0;
  let created = 0;
  let unchanged = 0;
  let deleted = 0;
  let errors = 0;
  for (const result of results) {
    switch (result.status) {
      case "created":
        p7.log.success(`${result.filePath} (criado)`);
        created++;
        break;
      case "updated":
        p7.log.success(`${result.filePath} (atualizado)`);
        updated++;
        break;
      case "unchanged":
        p7.log.step(`${result.filePath} (sem alteracoes)`);
        unchanged++;
        break;
      case "deleted":
        p7.log.warn(`${result.filePath} (removido)`);
        deleted++;
        break;
      case "error":
        p7.log.error(`${result.filePath}: ${result.error}`);
        errors++;
        break;
    }
  }
  const parts = [];
  if (created > 0) parts.push(`${created} criado(s)`);
  if (updated > 0) parts.push(`${updated} atualizado(s)`);
  if (deleted > 0) parts.push(`${deleted} removido(s)`);
  if (unchanged > 0) parts.push(`${unchanged} sem alteracoes`);
  if (errors > 0) parts.push(`${errors} erro(s)`);
  p7.log.info(`${results.length} providers processados (${parts.join(", ")})`);
  if (config.providers.includes("copilot-cli")) {
    if (ensureShellAlias("copilot", "copilot --additional-mcp-config @.copilot/mcp-config.json")) {
      p7.log.success('Alias "copilot" configurado no shell (execute "source ~/.zshrc" ou reinicie o terminal).');
    }
  }
}

