import * as p9 from "@clack/prompts";
import pc2 from "picocolors";
async function statusCommand(ctx) {
  const store = new ConfigStore(ctx.projectRoot);
  if (!store.exists()) {
    p9.log.warn("Nenhum .mcpx.json encontrado neste diretorio.");
    p9.log.info('Execute "mcpx init" para criar uma configuracao.');
    return;
  }
  const config = store.load();
  const registry = createRegistry();
  const serverCount = Object.keys(config.servers).length;
  let hasDesync = false;
  const lines = [];
  for (const providerName of config.providers) {
    const provider = registry.get(providerName);
    if (!provider) continue;
    const filePath = provider.getConfigFilePath(ctx.projectRoot);
    const expectedContent = provider.generate(config.servers);
    const displayPath = provider.config.supportsProjectConfig ? provider.config.configPath : provider.config.globalConfigPath ?? provider.config.configPath;
    let status;
    if (!fileExists(filePath)) {
      status = pc2.red("ausente");
      hasDesync = true;
    } else {
      const currentContent = readTextFile(filePath);
      if (currentContent === expectedContent) {
        status = pc2.green("sync");
      } else {
        status = pc2.yellow("desync");
        hasDesync = true;
      }
    }
    lines.push(`${pc2.bold(provider.config.displayName.padEnd(16))} ${displayPath.padEnd(30)} ${status}`);
  }
  p9.note(
    lines.join("\n"),
    `${serverCount} servidor(es), ${config.providers.length} provider(s)`
  );
  if (hasDesync) {
    p9.log.warn('Alguns providers estao desatualizados. Execute "mcpx sync" para atualizar.');
  } else {
    p9.log.success("Todos os providers estao sincronizados.");
  }
}

// src/cli.ts
function createCli() {
  const program2 = new Command();
  program2.name("mcpx").description("CLI para configurar servidores MCP para multiplos providers de IA").version("0.1.0").option("-d, --dir <path>", "Diretorio do projeto", process.cwd()).option("--verbose", "Exibe logs detalhados", false);
  function getContext() {
    const opts = program2.opts();
    return {
      projectRoot: opts["dir"],
      verbose: opts["verbose"]
    };
  }
  program2.command("init").description("Wizard interativo para configuracao inicial").action(() => initCommand(getContext()));
  program2.command("add").description("Adiciona um servidor MCP").argument("[name]", "Nome do servidor").action((name) => addCommand(getContext(), name));
  program2.command("remove").description("Remove um servidor MCP").argument("[name]", "Nome do servidor").action((name) => removeCommand(getContext(), name));
  program2.command("list").description("Lista servidores MCP configurados").action(() => listCommand(getContext()));
  program2.command("sync").description("Regenera arquivos de configuracao dos providers").action(() => syncCommand(getContext()));
  program2.command("import").description("Importa configuracao de um provider existente").argument("[provider]", "Nome do provider").action((provider) => importCommand(getContext(), provider));
  program2.command("status").description("Mostra estado de sincronia dos providers").action(() => statusCommand(getContext()));
  program2.action(() => initCommand(getContext()));
  return program2;
}

// bin/mcpx.ts
var program = createCli();
program.parseAsync(process.argv).catch((err) => {
  console.error(err);
  process.exit(1);
});
